import{_ as t,o,c as a,a2 as d}from"./chunks/framework.D0xy3_1I.js";const u=JSON.parse('{"title":"QA checks (self-QA)","description":"","frontmatter":{},"headers":[],"relativePath":"qa.md","filePath":"qa.md"}'),s={name:"qa.md"};function c(i,e,n,r,h,l){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="qa-checks-self-qa" tabindex="-1">QA checks (self-QA) <a class="header-anchor" href="#qa-checks-self-qa" aria-label="Permalink to &quot;QA checks (self-QA)&quot;">​</a></h1><p>In-page checks live in <code>window.__qa</code> (<code>game/src/main.js</code>). Procedure: <code>.claude/skills/qa-motion/SKILL.md</code>. To run one: build (<code>npm run spike:prepare</code>), open the game with a new <code>?v=N</code>, click the blank border of the page so the window has focus (an unfocused window pauses the game), start a level with <code>window.__ff.newLevel(&lt;level&gt;)</code>, wait about 10 s, dismiss any intro pop-up, then <code>await window.__qa.&lt;name&gt;()</code> and read <code>pass</code> and the counts.</p><table tabindex="0"><thead><tr><th>check</th><th>what it measures</th><th>pass when</th></tr></thead><tbody><tr><td><code>octRelease()</code></td><td>octopus tapped into the Backup, then released into the tank (frame by frame)</td><td>size steps &lt;= 12% per frame; angle step &lt;= 0.35 rad; not hidden by the Backup tray; no hang in the air; the 3D speed at the hand-off equals the flying picture&#39;s (0.65x to 1.5x); no jerk &gt; 3.5 units/s; nothing outside the glass while it falls in</td></tr><tr><td><code>fishRelease()</code></td><td>a fish tapped into the Backup and released: speed every frame</td><td>no jump &gt; 3.5 units/s between frames, no stop while diving</td></tr><tr><td><code>fishClip(sec)</code></td><td>fish bodies (middle, nose, tail) inside solid decor</td><td>0 samples inside</td></tr><tr><td><code>decorFit()</code></td><td>every visible decor piece of every look: sticking out through the glass, solid pieces overlapping on the floor, soft pieces standing inside solid ones</td><td>0 pieces out of the glass, 0 overlapping pairs, 0 soft-in-solid</td></tr><tr><td><code>overlapAudit(sec)</code></td><td>everything visible in the tank: decor against decor, clams against decor and each other (static), and sampled over time fish, jellyfish, octopus and clams against solid decor and against each other</td><td>0 in every count (<code>fishFishEvent</code> counts fish that overlap during an event and is expected to be above 0 while one runs)</td></tr><tr><td><code>jitter(sec)</code></td><td>the smoothness of the swimming: per frame, how far each fish moved (<code>stepP50</code>, <code>stepP99</code>, <code>stepMax</code>) and how much that changed (<code>acc*</code>); <code>jumps</code> = steps over 0.18 in one frame</td><td><code>jumps</code> close to 0 (a browser hitch shows as a few; a crowded level has a handful) and no teleport-sized <code>stepMax</code></td></tr></tbody></table><h2 id="test-hooks-window-ff" tabindex="-1">Test hooks (<code>window.__ff</code>) <a class="header-anchor" href="#test-hooks-window-ff" aria-label="Permalink to &quot;Test hooks (`window.__ff`)&quot;">​</a></h2><p><code>newLevel(n)</code>, <code>save</code> (the saved progress object, e.g. delete <code>save.iClear</code> to see an introduction again), <code>state()</code> (paused, introOn, popupOn, ready), <code>pick(fish)</code> (a tap on that fish), <code>devWin()</code> (play the win sequence), <code>devEvent(name)</code>, <code>showPlayOn()</code>, <code>showLose()</code>, <code>sprayInk(...)</code>, <code>modelVariant(...)</code>, <code>evFreeIn()</code> (seconds of quiet left), <code>feed</code> (the food state), plus <code>G</code>, <code>orbit</code>, <code>THUMB</code>, <code>SPECIES</code>. <code>window.__hue</code> has the colour-turn helpers (<code>toxic</code>, <code>pick</code>, <code>turn</code>); <code>?oldhue=1</code> switches back to the old colour turn to compare.</p><h2 id="habits-that-found-real-bugs" tabindex="-1">Habits that found real bugs <a class="header-anchor" href="#habits-that-found-real-bugs" aria-label="Permalink to &quot;Habits that found real bugs&quot;">​</a></h2><ul><li><p>Measure <strong>per frame</strong> (not a few pictures) and compare with the same measure before the change.</p></li><li><p>Test at a <strong>small tank shape</strong> (heart, bowl) and at a crowded level (55-60) as well as an easy one.</p></li><li><p>After a change to fish movement, run <code>jitter</code> and <code>fishClip</code>; after a change to decor, run <code>decorFit</code> and <code>overlapAudit</code>.</p></li><li><p>Test pop-ups by stretching the closing delay (so a change of buttons while closing becomes visible), and hide the tab to test the paused game.</p></li><li><p>After deleting or renaming any asset, search the code for its name, then play a win (LEVEL COMPLETE shows) and a combo (NICE / GREAT show): some pictures load lazily, so a missing file does not show as a failed request at start.</p></li><li><p>Win with fish in the Backup: put fish in the Backup, remove the rest from the tank, <code>devWin()</code>; the win must start at about 2.2 s, all Backup fish must join, WELL DONE must open.</p></li></ul><p>Add a check here every time a new class of defect is found.</p>',8)])])}const f=t(s,[["render",c]]);export{u as __pageData,f as default};
